mapper.select:
        select
       *
        from
        wms_transfer_buy_in
        where
        bool_delete_enum = 0
        
            and workshop_id = #{workshopId}
        
        
            and warehouse_id = #{warehouseId}
        
        
            and basic_class & #{ basicClass} > 0
        
        
            AND material_is_whole = #{materialIsWhole}
        
        
          and classify_id in
            
                #{item}
            
        



        
            
                and create_time > #{createTime[0]}
            
            
                and create_time < #{createTime[1]}
            
        
        
            and project_id = #{projectId}
        
        
            and width = #{width}
        
        
            and length = #{length}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and quantity >= #{minLength}
        
        
            and quantity <= #{maxLength}
        
        
            and theory_thickness = #{theoryThickness}
        
        
            and thickness = #{thickness}
        
        
            and color like CONCAT('%', #{color},'%')
        
        
            and specification like CONCAT('%', #{specification},'%')
        
        
            and heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND brand like CONCAT('%',#{brand},'%')
        
        
            and workshop_id in
            
                #{item}

        select
        wtbi.*,
        wtbi.create_time wct,
        wc.name classifyName,
        wm.*,
        wt.serial_number wsn,
        p.name spName
        from wms_transfer_buy_in wtbi
        left join wms_transfer wt on wt.id = wtbi.transfer_id
        left join contract_project p on p.id = wtbi.project_id
        left join wms_classification wc on wtbi.classify_id = wc.id
        left join wms_measure wm on wm.classification_id = wtbi.classify_id
        where
        wtbi.bool_delete_enum = 0
        
            and wtbi.basic_class = #{basicClass}
        
        
            and wtbi.bool_party_a = 1
        
        
            and wtbi.bool_party_a = 0
        
        
            
                and wtbi.create_time > #{outboundTime[0]}
            
            
                and wtbi.create_time < #{outboundTime[1]}
            
        
        
            and wtbi.classify_id in
            
                #{item}
            
        



        
            and wtbi.width = #{width}
        
        
            and wtbi.length = #{length}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and wtbi.quantity >= #{minLength}
        
        
            and wtbi.quantity <= #{maxLength}
        
        
            and wtbi.theory_thickness = #{theoryThickness}
        
        
            and wtbi.thickness = #{thickness}
        
        
            and wtbi.color like CONCAT('%', #{color},'%')
        
        
            and wtbi.specification like CONCAT('%', #{specification},'%')
        
        
            and wtbi.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wtbi.brand like CONCAT('%',#{brand},'%')
        
        
            and wtbi.workshop_id in
            
                #{item}
            
        
        order by wtbi.id desc
